  ('aufliang', 'aufliang', '', '', '', 'Grundwortschatz Wienerisch', 'anfliegen', '[{"kategorie": "wörtlich", "text": "\"wie ein Vogel auf etwas zusteuern\" (vom althochdeutschen \"fliogan\"=\"fliegen\")"}, {"kategorie": "allg.", "text": "etwas ansteuern, auf etwas zusteuern"}, {"kategorie": "fig.", "text": "jemanden provozieren, angehen, belästigen, anpöbeln ([[Dea fliagd an jedn au, dea si bewegd!]])"}, {"kategorie": "", "text": "jemanden anbetteln, anschnorren, anpumpen"}, {"kategorie": "ein Mädchen", "text": "ansprechen, anflirten, anmachen, anbaggern"}]'::jsonb, 'Wea Wean min Fliiga aufliagt, waass: rechtzeitich grantich wean!'),
  ('aulassich', 'aulassich', '', '', '', 'Grundwortschatz Wienerisch', 'anlassig', '[{"kategorie": "wörtlich", "text": "\"Anlass zu etwas gebend\" (dialektale Ableitung vom mittelhochdeutschen \"anlāz\"=\"Beginn, Grund, Gelegenheit\")"}, {"kategorie": "allg.", "text": "aufdringlich, penetrant, zudringlich, übergriffig"}]'::jsonb, 'Dea is mea ois aulassich - I füü mi richtig bedrängd von dem!'),
