  ('ausbaanln', 'ausbaanln', '', '', '', 'Grundwortschatz Wienerisch', 'ausbeinen', '[{"kategorie": "wörtlich", "text": "\"ausbeinen\" (vom mittelhochdeutschen \"ûzbeinen\"=\"ausbeinen\")"}, {"kategorie": "Fleischhauerjargon", "text": "\"Knochen vom Fleisch lösen\", Knochen entfernen, auslösen, entbeinen"}, {"kategorie": "Mechanikerjargon", "text": "\"auskernen\" (alle noch brauchbaren Teile aus Wracks ausbauen), ausschrotten (alle noch brauchbaren Reste verwerten), ausschlachten"}]'::jsonb, 'Beim Ausbaanln zööd jeeda Haundgriff - do meaksd glei, obs aana gleand hod oda ned!'),
  ('ausbaanla', 'Ausbaanla', 'der', '', '', 'Grundwortschatz Wienerisch', 'Ausbeiner', '[{"kategorie": "wörtlich", "text": "\"Ausbeiner\" (vom mittelhochdeutschen \"ûzbeinen\"=\"ausbeinen\")"}, {"kategorie": "allg.", "text": "\"Fleischzerleger\" (Fleischhauer, der das Fleisch \"ausbeint\", d.h. alle Knochen aus dem Fleisch entfernt), \"Fleischzerteiler\", \"Metzger\""}, {"kategorie": "Mechanikerjargon", "text": "Autometzger (jemand, der ein Auto komplett zerlegt und bis auf die letzten noch brauchbaren Reste verwertet), Autowrackverwerter, Ausschrotter"}]'::jsonb, 'De Ausbaanla san de Kiruagn unta de Fleischhocka!'),
  ('aussackln', 'aussackln', '', '', '', 'Grundwortschatz Wienerisch', 'aussackeln', '[{"kategorie": "wörtlich", "text": "\"die Hosentaschen leerräumen\" (vom mittelhochdeutschen \"sac\"=\"Hosensack\")"}, {"kategorie": "allg.", "text": "die Hosentaschen vor dem Waschen leerräumen, die Hosensäcke leeren"}, {"kategorie": "fig.", "text": "jemandem das Geld aus der Tasche ziehen, jemanden ausnehmen, schröpfen, abzocken, jemandem das letzte Geld abnehmen"}]'::jsonb, 'I loss mi von meina Oidn sicha ned aussackln!'),
  ('ausschnopsn', 'ausschnopsn', '', '', '', 'Grundwortschatz Wienerisch', 'ausschnapsen', '[{"kategorie": "wörtlich", "text": "\"etwas durch eine Runde Schnaps oder beim [[Schnapsen]] (Kartenspiel) entscheiden\" (von \"schnapsen\"=\"ein Spiel um einen Schnaps spielen\")"}, {"kategorie": "fig.", "text": "etwas ausverhandeln, absprechen, verabreden, vereinbaren, [[auspaldofern]], [[auskarteln]]"}]'::jsonb, 'Des miass ma uns no ausschnopsn!'),
  ('schnopsn', 'Schnopsn', 'das', '', '', 'Wiener Kartentipplerjargon', 'Schnapsen', '[{"kategorie": "wörtlich", "text": "\"Schnapsen\" (Kartenspiel, das durch eine Runde Schnaps entschieden wird, d.h. der Gewinner bekommt einen Schnaps, der Verlierer zahlt)"}, {"kategorie": "Kartenspielerjargon", "text": "Zweierschnapsen (Kartenspiel für zwei Spieler, ähnlich dem Kartenspiel \"66\": Ziel des Spiels ist es, durch Stiche und Ansagen möglichst schnell 66 Punkte zu erreichen. Es wird von 7 auf null heruntergespielt, der Verlierer bekommt ein [[Bummerl]]. Hat der Verlierer am Ende kein einziges Spiel gewonnen, hat dies einen [[Schneider]] [[[zwei]] Bummerln] zur Folge)"}]'::jsonb, 'Schnopsn is nix fia Reisgänga - wäu do haassds ''schdechn'' oda ''schdeam''!'),
  ('baa', 'Baa', 'das', '', '', 'Grundwortschatz Wienerisch', 'Bein', '[{"kategorie": "wörtlich", "text": "\" Gebein\" (Plural: [[Baana]], vom mittelhochdeutschen \"bein\"=\"Knochen\")"}, {"kategorie": "allg.", "text": "Knochen, lateinisch: \"Os\""}, {"kategorie": "fig.", "text": "unangenehmer Zeitgenosse, \"Knochen\", \"Laus\" (siehe [[Dea is a gsunds Baa - do hüüfd ka Weiwossa, fia den brauchst an Pfeffasprej!]])"}, {"kategorie": "scherzhaft für", "text": "nicht attraktive, abgemagerte, knochige Frau, \"Knochen\""}, {"kategorie": "Gaunersprache", "text": "Prostituierte, Strichmädchen, Sexarbeiterin, [[Schlampe]], [[Asphaltschwalbe]], [[Gürtelschnalle]], [[Ross]], [[Wetzen]]"}]'::jsonb, 'Bei mia deaf im Fleischschdickl ka anzigs Baa sei!'),
  ('baana', 'Baana', 'die', '', '', 'Grundwortschatz Wienerisch', 'Gebeine', '[{"kategorie": "", "text": "\"Knochen\" (Plural von \"Baa\", vom mittelhochdeutschen \"bein\"=\"Knochen\")"}, {"kategorie": "allg.", "text": "Gebeine, Knochengerüst, Skelett"}, {"kategorie": "scherzhaft für", "text": "nicht attraktive, abgemagerte, knochige Frauen, \"Knochen\", \"Hungerhaken\""}, {"kategorie": "Gaunersprache", "text": "Prostuierte, [[Asphaltschwalbe]], [[Gürtelschnallen]], [[Rösser]], [[Wetzen]]"}]'::jsonb, 'Mia tuan de Baana wee!'),
  ('boodewaschl', 'Boodewaschl', 'der', '', '', 'Grundwortschatz Wienerisch', 'Badewaschel', '[{"kategorie": "wörtlich", "text": "\"Bademeister\" (geht zurück auf die mittelalterlichen Wiener Badestuben, deren Aufseher \"der Bader\" war. Wenn man sich den Rücken schrubben lassen wollte, rief man \"Bader, waschen!\" - woraus sich die verballhornte Form \"Badewaschel\" entwickelt hat)"}, {"kategorie": "allg.", "text": "Aufseher in einem Schwimmbad, Badeaufseher, Badwart, Schwimmeister, \"Bademantel-Bulle\""}]'::jsonb, 'Da Boodewaschl sitzt am Becknraund wia da Poseidon mit Sonnanbrüün!'),
